@@ -0,0 +1,116 @@
+/**
+ * =============================================================================
+ * KS-2173 — the 'Vote delegated' log call holds no wallet address
+ * =============================================================================
+ * `delegateVote` used to log `{ delegationId, delegatorAddress, delegateAddress }`,
+ * so every delegation wrote BOTH wallet addresses into the governance service log.
+ * A wallet address is the data subject's own data (KS-1955); it must not reach a log
+ * line. The call now logs `{ delegationId }` alone (Wednesday's ruling: no other id is
+ * added, because whether a participant id is personal data is not measured).
+ *
+ * The delegation RECORD keeps both addresses (that is stored state, not a log line):
+ * the control cell below pins that, so a fix that reached the record would fail it.
+ *
+ * Harness: the real `delegateVote` over a SMALL `../db` dispatcher that answers only the
+ * four statements `delegateVote` issues (two participant reads by id, one active-delegations
+ * read that returns no rows, one delegation save) and refuses any other statement, plus a
+ * `../utils/logger` that records every call at every level. The cells run the call for real
+ * and read what the logger was handed, not a mock call count of the code under test.
+ *
+ * Cells: C1 and C2 are controls, they pass before and after the fix (the call is REACHED
+ * exactly once, so a cell that never reaches the log line cannot pass vacuously, and the
+ * record keeps both addresses); T1 and T2 are red against the unchanged code.
+ * Scope: the `Vote delegated` call only. The request log in index.ts and the shared
+ * errorHandler are the other layers of KS-2173 (part 2) and are NOT tested here.
+ * =============================================================================
+ */
+
+const WALLET_DELEGATOR = 'addr_test1qks2173delegatorwallet0000000000000000000000000000000000000';
+const WALLET_DELEGATE = 'addr_test1qks2173delegatewallet11111111111111111111111111111111111111';
+
+type Row = Record<string, unknown>;
+
+const mockH = {
+  participants: new Map<string, Row>(),
+  saves: [] as unknown[][],
+  logged: [] as { level: string; args: unknown[] }[],
+};
+
+function mockQuery(text: string, params: unknown[] = []): Promise<{ rows: Row[] }> {
+  if (/FROM svc_governance_participants WHERE id = \$1/.test(text)) {
+    const row = mockH.participants.get(String(params[0]));
+    return Promise.resolve({ rows: row ? [row] : [] });
+  }
+  if (/^\s*SELECT \* FROM svc_vote_delegations/.test(text)) return Promise.resolve({ rows: [] });
+  if (/INSERT INTO svc_vote_delegations/.test(text)) {
+    mockH.saves.push(params);
+    return Promise.resolve({ rows: [] });
+  }
+  return Promise.reject(new Error('KS-2173 harness: unexpected statement ' + text.slice(0, 60)));
+}
+
+jest.mock('../db', () => ({
+  isDbAvailable: () => true,
+  query: (text: string, params?: unknown[]) => mockQuery(text, params),
+  getLinkedWalletAddress: async () => null,
+  getUserIdsByLinkedWallet: async () => [],
+}));
+jest.mock('../utils/logger', () => ({
+  logger: {
+    info: (...a: unknown[]) => { mockH.logged.push({ level: 'info', args: a }); },
+    warn: (...a: unknown[]) => { mockH.logged.push({ level: 'warn', args: a }); },
+    debug: (...a: unknown[]) => { mockH.logged.push({ level: 'debug', args: a }); },
+    error: (...a: unknown[]) => { mockH.logged.push({ level: 'error', args: a }); },
+  },
+}));
+
+import { delegateVote } from '../services/governanceService';
+
+function participant(id: string, wallet: string): Row {
+  return { id, wallet_address: wallet, staked_amount: 1000, tier: 'basic', vote_power: 10, is_drep: false, is_constitutional_committee: false };
+}
+
+beforeEach(() => {
+  mockH.participants = new Map([
+    ['participant-delegator', participant('participant-delegator', WALLET_DELEGATOR)],
+    ['participant-delegate', participant('participant-delegate', WALLET_DELEGATE)],
+  ]);
+  mockH.saves = [];
+  mockH.logged = [];
+});
+
+describe('KS-2173 the Vote delegated log call holds no wallet address', () => {
+  it('control C1: a healthy delegation reaches the log call exactly once and saves once', async () => {
+    const delegation = await delegateVote('participant-delegator', 'participant-delegate', true);
+    const calls = mockH.logged.filter((l) => l.level === 'info' && l.args[0] === 'Vote delegated');
+    expect(calls).toHaveLength(1);
+    expect(mockH.saves).toHaveLength(1);
+    expect(delegation.id).toEqual(expect.any(String));
+  });
+
+  it('control C2: the delegation record still keeps both addresses (the fix is the log line only)', async () => {
+    const delegation = await delegateVote('participant-delegator', 'participant-delegate', true);
+    expect(delegation.delegatorAddress).toBe(WALLET_DELEGATOR);
+    expect(delegation.delegateAddress).toBe(WALLET_DELEGATE);
+    expect(mockH.saves[0]).toEqual(expect.arrayContaining([WALLET_DELEGATOR, WALLET_DELEGATE]));
+  });
+
+  it('T1 the Vote delegated meta holds neither wallet address', async () => {
+    await delegateVote('participant-delegator', 'participant-delegate', true);
+    const calls = mockH.logged.filter((l) => l.level === 'info' && l.args[0] === 'Vote delegated');
+    expect(calls).toHaveLength(1); // REACHED: without this the cell would pass vacuously
+    const meta = JSON.stringify(calls[0].args[1]);
+    expect(meta).not.toContain(WALLET_DELEGATOR);
+    expect(meta).not.toContain(WALLET_DELEGATE);
+  });
+
+  it('T2 the Vote delegated meta is the delegation id alone, and no log call at any level carries a wallet address', async () => {
+    const delegation = await delegateVote('participant-delegator', 'participant-delegate', true);
+    const calls = mockH.logged.filter((l) => l.level === 'info' && l.args[0] === 'Vote delegated');
+    expect(calls).toHaveLength(1);
+    expect(calls[0].args[1]).toEqual({ delegationId: delegation.id });
+    const everything = JSON.stringify(mockH.logged);
+    expect(everything).not.toContain(WALLET_DELEGATOR);
+    expect(everything).not.toContain(WALLET_DELEGATE);
+  });
+});

